-- Modify "order_items" table
ALTER TABLE "order_items" ADD COLUMN "goods_type" character varying NOT NULL DEFAULT 'virtual', ADD COLUMN "paid_amount" bigint NOT NULL DEFAULT 0, ADD COLUMN "shipping_amount" bigint NOT NULL DEFAULT 0, ADD COLUMN "refunded_amount" bigint NOT NULL DEFAULT 0, ADD COLUMN "refunded_shipping" bigint NOT NULL DEFAULT 0, ADD COLUMN "canceled_quantity" integer NOT NULL DEFAULT 0, ADD COLUMN "shipped_quantity" integer NOT NULL DEFAULT 0, ADD COLUMN "received_quantity" integer NOT NULL DEFAULT 0, ADD COLUMN "returned_quantity" integer NOT NULL DEFAULT 0;
-- Modify "orders" table
ALTER TABLE "orders" ADD COLUMN "commerce_version" integer NOT NULL DEFAULT 0, ADD COLUMN "shipping_amount" bigint NOT NULL DEFAULT 0, ADD COLUMN "shipping_status" character varying NOT NULL DEFAULT 'none', ADD COLUMN "shipping_address" jsonb NULL, ADD COLUMN "request_hash" character varying NOT NULL DEFAULT '';
-- Modify "product_skus" table
ALTER TABLE "product_skus" ADD COLUMN "physical_stock" bigint NOT NULL DEFAULT 0;
-- Modify "products" table
ALTER TABLE "products" ADD COLUMN "goods_type" character varying NOT NULL DEFAULT 'virtual', ADD COLUMN "shipping_mode" character varying NOT NULL DEFAULT 'free', ADD COLUMN "shipping_fee" bigint NOT NULL DEFAULT 0, ADD COLUMN "shipping_countries" jsonb NULL, ADD COLUMN "physical_stock" bigint NOT NULL DEFAULT 0;
-- Modify "refund_orders" table
ALTER TABLE "refund_orders" ADD COLUMN "item_allocations" jsonb NULL, ADD COLUMN "shipping_amount" bigint NOT NULL DEFAULT 0;
-- Create "physical_stock_movements" table
CREATE TABLE "physical_stock_movements" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "product_id" bigint NOT NULL, "sku_id" bigint NOT NULL DEFAULT 0, "order_id" bigint NOT NULL DEFAULT 0, "delta" bigint NOT NULL, "reference" character varying NOT NULL, "reason" character varying NOT NULL, PRIMARY KEY ("id"));
-- Create index "physical_stock_movements_reference_key" to table: "physical_stock_movements"
CREATE UNIQUE INDEX "physical_stock_movements_reference_key" ON "physical_stock_movements" ("reference");
-- Create index "physicalstockmovement_order_id" to table: "physical_stock_movements"
CREATE INDEX "physicalstockmovement_order_id" ON "physical_stock_movements" ("order_id");
-- Create index "physicalstockmovement_product_id_sku_id" to table: "physical_stock_movements"
CREATE INDEX "physicalstockmovement_product_id_sku_id" ON "physical_stock_movements" ("product_id", "sku_id");
-- Create "shipments" table
CREATE TABLE "shipments" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "order_id" bigint NOT NULL, "carrier" character varying NOT NULL, "tracking_no" character varying NOT NULL, "items" jsonb NOT NULL, "address" jsonb NOT NULL, "status" character varying NOT NULL DEFAULT 'shipped', "admin_id" bigint NOT NULL, "request_key" character varying NOT NULL, "received_at" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "shipment_order_id" to table: "shipments"
CREATE INDEX "shipment_order_id" ON "shipments" ("order_id");
-- Create index "shipment_subsite_id_status" to table: "shipments"
CREATE INDEX "shipment_subsite_id_status" ON "shipments" ("subsite_id", "status");
-- Create index "shipments_request_key_key" to table: "shipments"
CREATE UNIQUE INDEX "shipments_request_key_key" ON "shipments" ("request_key");
